package com.akhil.perf; import jakarta.persistence.*; @Entity @Table(name="products",indexes=@Index(name="idx_products_category",columnList="category")) public class Product implements java.io.Serializable{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false) String name; @Column(nullable=false) String category; double price; public Long getId(){return id;} public String getName(){return name;} public String getCategory(){return category;} public double getPrice(){return price;} public void setName(String x){name=x;} public void setCategory(String x){category=x;} public void setPrice(double x){price=x;}}